import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

const ROOT = join(import.meta.dirname, '..');
const read = (path: string) => readFileSync(join(ROOT, path), 'utf8');

/** The screenshots generated by `pnpm screenshots` and shown in the README. */
const SCREENSHOTS = [
  'dashboard',
  'vehicles',
  'vehicle-detail',
  'vehicle-stats',
  'settings',
  'vehicle-detail-dark',
  'mobile-dashboard',
];

describe('release docs and screenshots', () => {
  it('screenshots are not part of the e2e suite or vitest', () => {
    expect(read('e2e/playwright.config.ts')).toContain("testDir: './tests'");
    expect(read('e2e/vitest.config.ts')).toContain("include: ['*.test.ts']");
    const rootScripts = (JSON.parse(read('package.json')) as { scripts: Record<string, string> }).scripts;
    expect(rootScripts['test:e2e']).not.toContain('screenshots');
    expect(rootScripts.screenshots).toBe('pnpm build && pnpm --filter @ikrive/e2e screenshots');
    const e2eScripts = (JSON.parse(read('e2e/package.json')) as { scripts: Record<string, string> }).scripts;
    expect(e2eScripts['test:e2e']).not.toContain('screenshots');
  });

  it('readme shows every generated screenshot', () => {
    const script = read('e2e/screenshots/readme.spec.ts');
    const readme = read('README.md');
    for (const name of SCREENSHOTS) {
      expect(script, name).toContain(`'${name}.png'`);
      expect(readme, name).toContain(`docs/screenshots/${name}.png`);
      expect(existsSync(join(ROOT, 'docs/screenshots', `${name}.png`)), name).toBe(true);
    }
  });

  it('self-hosting guide covers install, backups and internet exposure', () => {
    const guide = read('docs/self-hosting.md');
    for (const text of [
      'docker compose',
      'DISABLE_SIGNUP',
      'docker compose pull',
      '/data',
      'ikrive.db',
      'uploads',
      '/api/me/export',
      'IMPORT_MAX_MB',
      'X-Forwarded-For',
      '/api/public/reports/',
      '/api/calendar/',
    ]) {
      expect(guide, text).toContain(text);
    }
  });

  it('readme links the guide without the env table', () => {
    const readme = read('README.md');
    expect(readme).toContain('docs/self-hosting.md');
    expect(readme).not.toContain('REPORT_MAX_ANNEX_MB');
  });
});
